// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title DistributedCacheClient
 * @notice Distributed cache with template-based key generation
 */
contract DistributedCacheClient is Ownable {
    struct CacheEntry {
        bytes value;
        uint256 expiry;
        address origin;
    }

    mapping(bytes32 => CacheEntry) private _cache;
    mapping(address => bool) public authorizedNodes;

    string public keyTemplate;
    string public regionPrefix;
    bool public templateLocked;

    event CacheSet(bytes32 indexed key, address indexed setter);
    event CacheEvicted(bytes32 indexed key);
    event TemplateUpdated(string newTemplate);

    modifier onlyAuthorized() {
        require(authorizedNodes[msg.sender] || msg.sender == owner(), "Not authorized");
        _;
    }

    constructor(string memory _region, string memory _template) {
        regionPrefix = _region;
        keyTemplate = _template;
        templateLocked = false;
        authorizedNodes[msg.sender] = true;
    }

    function addNode(address node) external onlyOwner {
        authorizedNodes[node] = true;
    }

    function removeNode(address node) external onlyOwner {
        authorizedNodes[node] = false;
    }

    function updateTemplate(string calldata newTemplate) external onlyOwner {
        require(!templateLocked, "Template is locked");
        keyTemplate = newTemplate;
        emit TemplateUpdated(newTemplate);
    }

    function lockTemplate() external onlyOwner {
        templateLocked = true;
    }

    function _renderTemplate(string memory input, address caller) internal view returns (bytes32) {
        bytes memory tmpl = bytes(keyTemplate);
        bytes memory result = new bytes(0);

        for (uint i = 0; i < tmpl.length; i++) {
            if (i + 1 < tmpl.length && tmpl[i] == '{' && tmpl[i+1] == '{') {
                uint j = i + 2;
                bytes memory varName = new bytes(0);
                while (j + 1 < tmpl.length && !(tmpl[j] == '}' && tmpl[j+1] == '}')) {
                    varName = abi.encodePacked(varName, tmpl[j]);
                    j++;
                }
                bytes memory resolved = _resolveVariable(varName, input, caller);
                result = abi.encodePacked(result, resolved);
                i = j + 1;
            } else {
                result = abi.encodePacked(result, tmpl[i]);
            }
        }
        return keccak256(result);
    }

    function _resolveVariable(bytes memory varName, string memory input, address caller) internal view returns (bytes memory) {
        if (_bytesEqual(varName, "region")) {
            return bytes(regionPrefix);
        } else if (_bytesEqual(varName, "key")) {
            return bytes(input);
        } else if (_bytesEqual(varName, "sender")) {
            return abi.encodePacked(caller);
        } else if (_bytesEqual(varName, "owner")) {
            return abi.encodePacked(owner());
        } else if (_bytesEqual(varName, "self")) {
            return abi.encodePacked(address(this));
        }
        return varName;
    }

    function _bytesEqual(bytes memory a, bytes memory b) internal pure returns (bool) {
        if (a.length != b.length) return false;
        for (uint i = 0; i < a.length; i++) {
            if (a[i] != b[i]) return false;
        }
        return true;
    }

    function set(string calldata key, bytes calldata value, uint256 ttl) external onlyAuthorized {
        bytes32 cacheKey = _renderTemplate(key, msg.sender);
        _cache[cacheKey] = CacheEntry({
            value: value,
            expiry: block.timestamp + ttl,
            origin: msg.sender
        });
        emit CacheSet(cacheKey, msg.sender);
    }

    function get(string calldata key) external view returns (bytes memory, bool) {
        bytes32 cacheKey = _renderTemplate(key, msg.sender);
        CacheEntry storage entry = _cache[cacheKey];
        if (entry.expiry == 0 || block.timestamp > entry.expiry) {
            return ("", false);
        }
        return (entry.value, true);
    }

    function getAs(string calldata key, address asUser) external view onlyOwner returns (bytes memory, bool) {
        bytes32 cacheKey = _renderTemplate(key, asUser);
        CacheEntry storage entry = _cache[cacheKey];
        if (entry.expiry == 0 || block.timestamp > entry.expiry) {
            return ("", false);
        }
        return (entry.value, true);
    }

    function evict(string calldata key) external onlyAuthorized {
        bytes32 cacheKey = _renderTemplate(key, msg.sender);
        delete _cache[cacheKey];
        emit CacheEvicted(cacheKey);
    }

    function computeKey(string calldata key) external view returns (bytes32) {
        return _renderTemplate(key, msg.sender);
    }
}
